export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed, g = inputs.gravity;
  const ta = u / g, T = 2 * ta, H = u * u / (2 * g);
  const t = sdk.clamp(time, 0, T);
  const S = 140, base = 380;
  const yt = u * t - g * t * t / 2;
  const vt = u - g * t;
  const rel = t >= ta;
  const tau = Math.max(0, t - ta);
  const yd = rel ? H - g * tau * tau / 2 : H;
  const vd = rel ? -g * tau : 0;
  const ad = rel ? -g : 0;
  const f = (v) => sdk.format(v, 2);
  const px = (y) => base - y * S;
  const o = [];
  const eps = 1e-9;
  const ts = t < eps ? 'At launch' : (Math.abs(t - ta) < 0.004 ? 'At the top' : (t < ta ? 'Rising' : (t < T - eps ? 'Falling' : 'At launch height')));
  const ds = !rel ? 'Held in place' : (t >= T - eps ? 'At launch height' : (tau < 0.1 ? 'Just released' : 'Falling together'));
  o.push(...sdk.panel({ id: 'lane.toss', x: 20, y: 40, w: 290, h: 370, title: 'Toss', state: ts }));
  o.push(...sdk.panel({ id: 'lane.drop', x: 330, y: 40, w: 290, h: 370, title: 'Drop', state: ds, role: 'warning' }));
  const cx1 = 175, cx2 = 485;
  o.push(...sdk.groundMark('mark.launch', cx1, base + 14, 120, 'launch mark'));
  o.push(...sdk.groundMark('mark.launch2', cx2, base + 14, 120, 'launch mark'));
  o.push(...sdk.gate('gate.drop', cx2, px(H) + 18, { open: rel, w: 40 }));
  if (rel) {
    o.push(sdk.circle('ghost.toss', cx1, px(H), 28, { opacity: 0.25 }));
    o.push(sdk.circle('ghost.drop', cx2, px(H), 28, { opacity: 0.25 }));
  }
  o.push(sdk.circle('ball.toss', cx1, px(yt), 28, { role: 'input' }));
  o.push(sdk.circle('ball.drop', cx2, px(yd), 28, { role: 'warning' }));
  o.push(...sdk.vector('vec.v.toss', { x: cx1 - 30, y: px(yt) }, { value: vt, direction: 'up' }, { scale: 12, label: 'v', role: 'input' }));
  o.push(...sdk.vector('vec.a.toss', { x: cx1 + 30, y: px(yt) }, { value: -g, direction: 'up' }, { scale: 5, label: 'a', role: 'warning' }));
  o.push(...sdk.vector('vec.v.drop', { x: cx2 - 30, y: px(yd) }, { value: vd, direction: 'up' }, { scale: 12, label: 'v', role: 'input' }));
  o.push(...sdk.vector('vec.a.drop', { x: cx2 + 30, y: px(yd) }, { value: ad, direction: 'up' }, { scale: 5, label: 'a', role: 'warning' }));
  o.push(...sdk.callout(30, 90, ['v = ' + f(vt) + ' m/s', 'a = ' + f(-g) + ' m/s²'], { id: 'callout.toss' }));
  o.push(...sdk.callout(340, 90, ['v = ' + f(vd) + ' m/s', 'a = ' + f(ad) + ' m/s²'], { id: 'callout.drop' }));
  const q = { launchSpeed: u, gravity: g, apexTime: ta, apexHeight: H, tossedVelocity: vt, tossedAcceleration: -g, tossedHeight: yt, dropVelocity: vd, dropAcceleration: ad, dropHeight: yd };
  return { frame: { width: 640, height: 420, objects: o, readouts: [
    { id: 'tossedVelocity', value: vt }, { id: 'tossedAcceleration', value: -g },
    { id: 'dropVelocity', value: vd }, { id: 'dropAcceleration', value: ad } ] }, quantities: q };
}
